"effects/outline.frag","font/slug.frag","font/slug.vert","core/textured-quad.frag","core/textured-quad.vert","texture/batch-preamble.glsl","lighting2d/light.frag","lighting2d/light.vert","model3d/lighting.frag","README.md","pathtrace/present.frag","pathtrace/present.vert","radiance-web/merge.frag","model3d/depth.frag","model3d/depth.vert","core/shape.frag","core/shape.vert","lighting2d/sprite-volume.frag","lighting2d/sprite-volume.vert","#version 330 core\r\n\r\nlayout(location = 0) in vec2 a_position;\r\n\r\nuniform mat4 u_mvp;\r\n\r\nvoid main() {\r\n    gl_Position = u_mvp * vec4(a_position, 0.0, 1.0);\r\n}\r\n",
"#version 330 core\r\n\r\nuniform sampler2D u_texture;\r\n\r\nin vec2 v_uv;\r\nin vec4 v_color;\r\n\r\nout vec4 fragColor;\r\n\r\nvoid main() {\r\n    fragColor = texture(u_texture, v_uv) * v_color;\r\n}\r\n","#version 330 core\r\n\r\nlayout(location = 0) in vec2 a_position;\r\nlayout(location = 1) in vec2 a_uv;\r\nlayout(location = 2) in vec4 a_color;\r\n\r\nuniform mat4 u_mvp;\r\n\r\nout vec2 v_uv;\r\nout vec4 v_color;\r\n\r\nvoid main() {\r\n    gl_Position = u_mvp * vec4(a_position, 0.0, 1.0);\r\n    v_uv = a_uv;\r\n    v_color = a_color;\r\n}\r\n",
"#version 330 core\r\nuniform sampler2D u_texture;\r\nuniform vec2 u_texelSize;\r\nuniform float u_radiusPx;\r\nin vec2 v_uv;\r\nin vec4 v_color;\r\nout vec4 fragColor;\r\nvoid main() {\r\n    float r = max(0.0, u_radiusPx);\r\n    vec2 o = u_texelSize * r;\r\n    vec4 sum = vec4(0.0);\r\n    sum += texture(u_texture, v_uv + vec2(-o.x, -o.y));\r\n    sum += texture(u_texture, v_uv + vec2(0.0, -o.y));\r\n    sum += texture(u_texture, v_uv + vec2(o.x, -o.y));\r\n    sum += texture(u_texture, v_uv + vec2(-o.x, 0.0));\r\n    sum += texture(u"
+"_texture, v_uv);\r\n    sum += texture(u_texture, v_uv + vec2(o.x, 0.0));\r\n    sum += texture(u_texture, v_uv + vec2(-o.x, o.y));\r\n    sum += texture(u_texture, v_uv + vec2(0.0, o.y));\r\n    sum += texture(u_texture, v_uv + vec2(o.x, o.y));\r\n    fragColor = (sum / 9.0) * v_color;\r\n}\r\n","#version 330 core\r\nuniform sampler2D u_texture;\r\nuniform float u_time;\r\nuniform float u_threshold;\r\nuniform vec4 u_burnColor;\r\nin vec2 v_uv;\r\nin vec4 v_color;\r\nout vec4 fragColor;\r\nfloat hash(vec2 p) {\r\n    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);\r\n}\r\nfloat noise(vec2 p) {\r\n    vec2 i = floor(p);\r\n    vec2 f = fract(p);\r\n    float a = hash(i);\r\n    float b = hash(i + vec2(1.0, 0.0));\r\n    float c = hash(i + vec2(0.0, 1.0));\r\n    float d = hash(i + vec2(1.0, 1.0));\r\n    vec2 u = f * f * (3"
+".0 - 2.0 * f);\r\n    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;\r\n}\r\nvoid main() {\r\n    vec4 c = texture(u_texture, v_uv) * v_color;\r\n    if (c.a <= 0.001) { fragColor = c; return; }\r\n    float n = noise(v_uv * 14.0 + vec2(u_time * 0.15, u_time * 0.10));\r\n    float th = clamp(u_threshold, 0.0, 1.0);\r\n    if (n < th) discard;\r\n    float edge = smoothstep(th, th + 0.10, n);\r\n    float hot = 1.0 - edge;\r\n    vec3 burnRgb = u_burnColor.rgb;\r\n    vec3 outRgb = mix(burnRgb, c.rgb, ed"
+"ge);\r\n    outRgb += burnRgb * hot * 0.65;\r\n    fragColor = vec4(outRgb, c.a);\r\n}\r\n","#version 330 core\r\nuniform sampler2D u_texture;\r\nuniform vec4 u_flashColor;\r\nuniform float u_amount;\r\n\r\nin vec2 v_uv;\r\nin vec4 v_color;\r\nout vec4 fragColor;\r\n\r\nvoid main() {\r\n    vec4 c = texture(u_texture, v_uv) * v_color;\r\n\r\n    float amt = clamp(u_amount, 0.0, 1.0);\r\n    if (amt <= 0.0 || c.a <= 0.001) {\r\n        fragColor = c;\r\n        return;\r\n    }\r\n\r\n    vec3 rgb = mix(c.rgb, u_flashColor.rgb, amt);\r\n    float a = c.a * mix(1.0, clamp(u_flashColor.a, 0.0, 1.0), amt);\r\n\r\n    fragColor = vec4(rgb, a);\r"
+"\n}\r\n","#version 330 core\r\nuniform sampler2D u_texture;\r\nuniform vec2 u_texelSize;\r\nuniform float u_radiusPx;\r\nuniform float u_intensity;\r\nuniform vec4 u_glowColor;\r\n\r\nin vec2 v_uv;\r\nin vec4 v_color;\r\nout vec4 fragColor;\r\n\r\nfloat aAt(vec2 uv) {\r\n    return texture(u_texture, uv).a;\r\n}\r\n\r\nvoid main() {\r\n    vec4 center = texture(u_texture, v_uv);\r\n    float a = center.a;\r\n\r\n    // Sprite pixels: draw normally.\r\n    if (a > 0.001) {\r\n        fragColor = center * v_color;\r\n        return;\r\n    }\r\n\r\n    // Glow for tra"
+"nsparent pixels: sample nearby alpha.\r\n    float r1 = max(1.0, u_radiusPx * 0.35);\r\n    float r2 = max(1.0, u_radiusPx * 0.70);\r\n    float r3 = max(1.0, u_radiusPx);\r\n\r\n    vec2 o1 = u_texelSize * r1;\r\n    vec2 o2 = u_texelSize * r2;\r\n    vec2 o3 = u_texelSize * r3;\r\n\r\n    float s = 0.0;\r\n\r\n    // 4-way + diagonals at 3 radii\r\n    s += aAt(v_uv + vec2(o1.x, 0.0));\r\n    s += aAt(v_uv + vec2(-o1.x, 0.0));\r\n    s += aAt(v_uv + vec2(0.0, o1.y));\r\n    s += aAt(v_uv + vec2(0.0, -o1.y));\r\n    s += aAt(v_uv + vec2("
+"o1.x, o1.y));\r\n    s += aAt(v_uv + vec2(-o1.x, o1.y));\r\n    s += aAt(v_uv + vec2(o1.x, -o1.y));\r\n    s += aAt(v_uv + vec2(-o1.x, -o1.y));\r\n\r\n    s += aAt(v_uv + vec2(o2.x, 0.0)) * 0.75;\r\n    s += aAt(v_uv + vec2(-o2.x, 0.0)) * 0.75;\r\n    s += aAt(v_uv + vec2(0.0, o2.y)) * 0.75;\r\n    s += aAt(v_uv + vec2(0.0, -o2.y)) * 0.75;\r\n    s += aAt(v_uv + vec2(o2.x, o2.y)) * 0.75;\r\n    s += aAt(v_uv + vec2(-o2.x, o2.y)) * 0.75;\r\n    s += aAt(v_uv + vec2(o2.x, -o2.y)) * 0.75;\r\n    s += aAt(v_uv + vec2(-o2.x, -o2.y)) * "
